import{_ as t,o,c as a,a6 as s}from"./chunks/framework.DtfPIzdJ.js";const u=JSON.parse('{"title":"app","description":"","frontmatter":{},"headers":[],"relativePath":"reference/app.md","filePath":"reference/app.md"}'),i={name:"reference/app.md"};function d(n,e,r,c,l,p){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="app" tabindex="-1">app <a class="header-anchor" href="#app" aria-label="Permalink to &quot;app&quot;">​</a></h1><p>The <code>app</code> declaration names your project and holds a few project-wide settings: a description, the development port and the default AI provider. Every project has exactly one, in <code>app.clb</code> at the project root. The CLI uses that file to find the project. The app declaration has no code and no dependencies. It is a list of <code>key value</code> settings.</p><h2 id="syntax" tabindex="-1">Syntax <a class="header-anchor" href="#syntax" aria-label="Permalink to &quot;Syntax&quot;">​</a></h2><div class="language-cluub vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cluub</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">app</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ShopApp</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  about</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;An online shop with AI product descriptions&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  port </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;claude&quot;</span></span></code></pre></div><p>The full shape:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>app Name</span></span>
<span class="line"><span>  [setting &lt;expression&gt;]...</span></span></code></pre></div><p>Each setting is a name followed by a value on one line. <code>app Name</code> with no settings is also valid.</p><h2 id="members-options" tabindex="-1">Members / options <a class="header-anchor" href="#members-options" aria-label="Permalink to &quot;Members / options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th><th>Required?</th><th>Default</th></tr></thead><tbody><tr><td><code>Name</code> (after <code>app</code>)</td><td>The project&#39;s name, in PascalCase (<a href="/home/reference/errors#e102">E102</a>). Used as the <code>&lt;title&gt;</code> of the built <code>index.html</code> (each page replaces it with its own title once it opens) and as the heading of <code>cluub explain</code>.</td><td>Yes</td><td>none</td></tr><tr><td><code>about &quot;text&quot;</code></td><td>One-line description, shown next to the name in <code>cluub explain</code>.</td><td>No</td><td>none</td></tr><tr><td><code>port N</code></td><td>The port <code>cluub dev</code> and <code>cluub start</code> listen on, unless <code>--port</code> or the <code>PORT</code> environment variable says otherwise.</td><td>No</td><td><code>3000</code></td></tr><tr><td><code>ai &quot;provider&quot;</code></td><td>Default AI provider for every <code>ask ai</code> that has no <code>using</code>. One of <code>&quot;claude&quot;</code>, <code>&quot;openai&quot;</code>, <code>&quot;gemini&quot;</code>, <code>&quot;ollama&quot;</code> (<code>&quot;anthropic&quot;</code> and <code>&quot;google&quot;</code> also work). Add a model after a colon: <code>&quot;claude:claude-sonnet-5-5&quot;</code>.</td><td>No</td><td>see below</td></tr><tr><td><code>aiKeys &quot;server&quot;</code></td><td>Whose AI keys pay: <code>&quot;server&quot;</code> (your key from <code>.env</code> or the environment), <code>&quot;user&quot;</code> (each end user&#39;s own key, required; your key is never used) or <code>&quot;either&quot;</code> (the user&#39;s key when they added one, else yours). See <a href="/home/guide/ai-keys">Your own AI keys</a>. Any other value is warning W108.</td><td>No</td><td><code>&quot;server&quot;</code></td></tr><tr><td><code>aiModel &quot;model-id&quot;</code></td><td>Model to use with the <code>ai</code> provider, as an alternative to the colon form.</td><td>No</td><td>the provider&#39;s default model</td></tr></tbody></table><p>No other settings exist. Any other name gives warning <a href="/home/reference/errors#w108">W108</a> (<code>Unknown app setting &quot;prot&quot;; it will be ignored.</code> with a &quot;Did you mean&quot; hint) and is ignored.</p><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to &quot;Behaviour&quot;">​</a></h2><p><strong>Finding the project.</strong> Every CLI command except <code>cluub new</code> looks for <code>app.clb</code> in the current folder and then in each parent folder. Without it you get <code>No Cluub project here (no app.clb found). Create one with cluub new my-app.</code></p><p><strong>Settings are expressions.</strong> Each value is compiled like any Cluub expression and evaluated when the server program starts, so text interpolation works, and <code>env.X</code> reads the environment (<code>ai env.AI_PROVIDER</code>, or <code>port env.APP_PORT</code>).</p><p><strong>Which port is used.</strong></p><p><code>cluub dev</code> and <code>cluub start</code> pick the port the same way, first match wins:</p><ol><li>the <code>--port</code> flag (<code>cluub start --port 8080</code>);</li><li>the <code>PORT</code> environment variable (what most hosting platforms set);</li><li>the app&#39;s <code>port</code> setting;</li><li><code>3000</code>.</li></ol><p><strong>Which AI provider and model are used</strong> for an <code>ask ai</code>, from highest priority to lowest:</p><ol><li><code>using &quot;provider[:model]&quot;</code> on that <code>ask ai</code>;</li><li>the app&#39;s <code>ai</code> setting;</li><li>the <code>CLUUB_AI</code> environment variable;</li><li>the first provider whose API key is present in the environment (<code>ANTHROPIC_API_KEY</code>, <code>OPENAI_API_KEY</code>, <code>GEMINI_API_KEY</code>, in that order);</li><li><code>ollama</code> (local, no key).</li></ol><p>The model comes from the <code>:model</code> part if given, else <code>aiModel</code> (when the provider is the one named in <code>ai</code>), else <code>CLUUB_&lt;PROVIDER&gt;_MODEL</code> (for example <code>CLUUB_CLAUDE_MODEL</code>), else the provider&#39;s default. Keys are never written in <code>app.clb</code>: they come from <code>.env</code>. A missing key fails the AI call at runtime with <code>No API key for claude. Run &quot;cluub ai set claude&quot; (or add ANTHROPIC_API_KEY=... to .env). Never put keys in code.</code> In tests the AI is always fake, whatever this setting says.</p><p><strong>Compile-time checks.</strong> Only one <code>app</code> per project (<a href="/home/reference/errors#e101">E101</a>). The name must be PascalCase (<a href="/home/reference/errors#e102">E102</a>). Unknown settings give W108. The app must be in a file at the project root (<a href="/home/reference/errors#e301">E301</a>). Text that looks like an API key is rejected (<a href="/home/reference/errors#e401">E401</a>), so a key can never be committed through <code>app.clb</code>. Setting values are checked like other expressions: unknown names are reported (<a href="/home/reference/errors#e105">E105</a>).</p><p><strong>Not a layer.</strong> Nothing can <code>uses</code> the app, and the app uses nothing.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>Message (example)</th><th>Fix</th></tr></thead><tbody><tr><td><a href="/home/reference/errors#e010">E010</a></td><td><code>Expected a value but found \`=\`.</code></td><td>Settings have no <code>=</code>: write <code>port 3000</code>.</td></tr><tr><td><a href="/home/reference/errors#e010">E010</a></td><td><code>Expected a setting but found the text &quot;port&quot;.</code></td><td>Setting names are plain words, not quoted.</td></tr><tr><td><a href="/home/reference/errors#e010">E010</a></td><td><code>Expected the app name but found the end of the line.</code></td><td>Write <code>app MyApp</code>.</td></tr><tr><td><a href="/home/reference/errors#e102">E102</a></td><td><code>&quot;my_app&quot; should be PascalCase (start with a capital letter, no underscores).</code> (hint: <code>Rename it to &quot;MyApp&quot;.</code>)</td><td>Rename the app.</td></tr><tr><td><a href="/home/reference/errors#e101">E101</a></td><td><code>Only one \`app\` declaration is allowed per project.</code> (hint: <code>Keep a single \`app\` in app.clb.</code>)</td><td>Delete the extra app declaration.</td></tr><tr><td><a href="/home/reference/errors#e105">E105</a></td><td><code>I don&#39;t know what &quot;claude&quot; is.</code></td><td>Quote text values: <code>ai &quot;claude&quot;</code>.</td></tr><tr><td><a href="/home/reference/errors#e301">E301</a></td><td><code>An app belongs in the &quot;project root (app.clb)&quot; folder, but &quot;ShopApp&quot; is in config/app.clb.</code></td><td>Move it to <code>app.clb</code> at the root.</td></tr><tr><td><a href="/home/reference/errors#e401">E401</a></td><td><code>This looks like a secret key written directly in the code.</code></td><td>Put the key in <code>.env</code>.</td></tr><tr><td><a href="/home/reference/errors#w108">W108</a></td><td><code>Unknown app setting &quot;prot&quot;; it will be ignored.</code> (hint: <code>Did you mean &quot;port&quot;?</code>)</td><td>Fix the setting name, or remove it. Known settings: <code>about</code>, <code>port</code>, <code>ai</code>, <code>aiModel</code>, <code>aiKeys</code>, <code>lang</code>.</td></tr></tbody></table><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><p><strong>1. The smallest project file.</strong></p><div class="language-cluub vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cluub</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">app</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Notes</span></span></code></pre></div><p><code>cluub dev</code> serves it on port 3000 (or <code>PORT</code> / <code>--port</code>), and <code>ask ai</code> picks a provider from your <code>.env</code>.</p><p><strong>2. A typical starter.</strong></p><div class="language-cluub vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cluub</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">app</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TodoAi</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  about</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;A full-stack starter: todos with an AI summary&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  port </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;claude&quot;</span></span></code></pre></div><p>With <code>.env</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ANTHROPIC_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">sk-ant-...</span></span></code></pre></div><p><strong>3. Choosing the model per environment.</strong></p><div class="language-cluub vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cluub</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">app</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SupportDesk</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  about</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Support tickets triaged by AI&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  port </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ai</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> env</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.SUPPORT_AI</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  aiModel </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gpt-4.1-mini&quot;</span></span></code></pre></div><p>With <code>SUPPORT_AI=openai</code> in <code>.env</code>, every <code>ask ai</code> uses OpenAI&#39;s <code>gpt-4.1-mini</code>. Be careful when the provider can change: <code>aiModel</code> applies to whatever provider <code>ai</code> names, so <code>SUPPORT_AI=ollama</code> would ask Ollama for a model called <code>gpt-4.1-mini</code>. In that case put the model in the variable instead (<code>SUPPORT_AI=openai:gpt-4.1-mini</code>) and drop <code>aiModel</code>. A single <code>ask ai ... using &quot;claude&quot;</code> still overrides both, and then <code>aiModel</code> is not used because the provider differs.</p><h2 id="edge-cases-limits" tabindex="-1">Edge cases &amp; limits <a class="header-anchor" href="#edge-cases-limits" aria-label="Permalink to &quot;Edge cases &amp; limits&quot;">​</a></h2><ul><li><strong>Unknown settings are only a warning</strong> (W108). A typo such as <code>prot 3000</code> still builds, and the port falls back to 3000.</li><li><strong><code>PORT</code> beats the app&#39;s <code>port</code>.</strong> On a host that sets <code>PORT</code>, the <code>port</code> setting has no effect; that is intended.</li><li><strong>An unknown provider in <code>ai</code></strong> is only reported at runtime, when an AI call fails with <code>Unknown AI provider &quot;gpt&quot;. Use one of: claude, openai, gemini, ollama.</code></li><li><strong>The file name is not enforced exactly.</strong> E301 only checks that the app is at the root; but the CLI finds projects by <code>app.clb</code>, so always use that name.</li><li><strong>No other configuration</strong> (database URLs, CORS, logging levels, feature flags) is read from the app. Read such values in services with <code>env.X</code>.</li><li><strong>The compiler can build without an app</strong> (the name defaults to <code>CluubApp</code>), which is what the playground does, but the CLI cannot.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/home/guide/structure">Project structure &amp; layers</a></li><li><a href="/home/guide/ai">AI guide</a></li><li><a href="/home/reference/cli">CLI reference</a></li><li><a href="/home/guide/install">Install guide</a></li></ul>`,38)])])}const g=t(i,[["render",d]]);export{u as __pageData,g as default};
